"""Public interface: validated, idempotent, non-overlapping, cancellable reservations.

Contract: RES-001/v1 + G2-OD-01 + G2-OD-02 + RES-002/v1 (G3). Schema version 3 lives in
``reservations_v2`` (table name kept; adds ``state`` and ``version``); legacy G1 tables are migrated from, never modified.
Concurrency claims apply to local SQLite in one tested process environment only.
"""
import hashlib
import json
import re
import sqlite3
from contextlib import closing
from dataclasses import dataclass
from datetime import datetime, timedelta
from pathlib import Path

SCHEMA_VERSION = 3
_TABLE = "reservations_v2"
_TIMEOUT = 30.0


@dataclass(frozen=True)
class Outcome:
    status: int
    code: str
    reservation_id: int | None = None
    replayed: bool = False


_SCHEMA = f"""CREATE TABLE {_TABLE} (
    id INTEGER PRIMARY KEY,
    trusted_member_id TEXT NOT NULL,
    asset_id TEXT NOT NULL,
    starts_at TEXT NOT NULL,
    ends_at TEXT NOT NULL,
    idempotency_key TEXT NOT NULL,
    fingerprint TEXT NOT NULL,
    state TEXT NOT NULL DEFAULT 'active' CHECK (state IN ('active', 'cancelled')),
    version INTEGER NOT NULL DEFAULT 1,
    UNIQUE (trusted_member_id, idempotency_key))"""
_INDEX = f"CREATE INDEX {_TABLE}_asset_time ON {_TABLE} (asset_id, starts_at, ends_at)"

_FIELDS = ("trusted_member_id", "asset_id", "starts_at", "ends_at", "idempotency_key")
# G1 columnar signatures authorized by G2-OD-01 (legacy_g1) and G2-OD-02 (retained AP-G1).
_COLUMNAR_G1 = ["id", "member_id", "asset_id", "starts_at", "ends_at", "request_key"]
_COLUMNAR_RECORDED = ["reservation_id", "trusted_member_id", "asset_id",
                      "starts_at", "ends_at", "idempotency_key"]
_TS = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z")


def _ident_ok(value) -> bool:
    return isinstance(value, str) and 0 < len(value) <= 128


def _parse(value):
    if not isinstance(value, str) or not _TS.fullmatch(value):
        return None
    try:
        return datetime.strptime(value, "%Y-%m-%dT%H:%M:%SZ")
    except ValueError:
        return None


def _validate(member, asset, start, end, key) -> str | None:
    """Return a distinct 422 code, or None when the request is valid."""
    if not all(_ident_ok(v) for v in (member, asset, key)):
        return "invalid-identifier"
    s, e = _parse(start), _parse(end)
    if s is None or e is None:
        return "invalid-timestamp"
    if not (timedelta(0) < e - s <= timedelta(hours=24)):
        return "invalid-interval"
    return None


def _fingerprint(asset, start, end) -> str:
    return hashlib.sha256(json.dumps([asset, start, end]).encode()).hexdigest()


def _connect(path, **kw):
    conn = sqlite3.connect(path, timeout=_TIMEOUT, isolation_level=None, **kw)
    return conn


def _tables(conn):
    return [r[0] for r in conn.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")]


def _columns(conn, table):
    quoted = '"' + table.replace('"', '""') + '"'
    return [r[1] for r in conn.execute(f"PRAGMA table_info({quoted})")]


def _legacy_rows(conn, tables):
    """Return public-field tuples (id, member, asset, start, end, key) from the single
    authorized legacy source, or raise ValueError when the schema is not authorized."""
    if len(tables) != 1:
        raise ValueError(f"owner mapping required: unsupported or competing tables {sorted(tables)}")
    name = tables[0]
    if name == "reservations":
        cols = _columns(conn, name)
        if cols not in (_COLUMNAR_G1, _COLUMNAR_RECORDED):
            raise ValueError(f"owner mapping required: unknown columns {cols}")
        q = ", ".join('"' + c + '"' for c in cols)
        return [tuple(r) for r in conn.execute(f'SELECT {q} FROM "reservations" ORDER BY 1')]
    if name == "bookings_v2":
        if _columns(conn, name) != ["booking_no", "payload"]:
            raise ValueError("owner mapping required: unknown bookings_v2 columns")
        rows = []
        for no, payload in conn.execute("SELECT booking_no, payload FROM bookings_v2 ORDER BY 1"):
            try:
                data = json.loads(payload)
            except (TypeError, ValueError):
                raise ValueError(f"owner mapping required: unreadable payload for {no}")
            if not isinstance(data, dict) or set(data) != set(_FIELDS):
                raise ValueError(f"owner mapping required: unexpected payload fields for {no}")
            rows.append((no, *(data[f] for f in _FIELDS)))
        return rows
    raise ValueError(f"owner mapping required: unknown schema table {name!r}")


def _check_legacy(rows):
    for rid, member, asset, start, end, key in rows:
        if not isinstance(rid, int) or _validate(member, asset, start, end, key):
            raise ValueError(f"owner mapping required: invalid legacy record {rid!r}")
    seen = set()
    for rid, member, _a, _s, _e, key in rows:
        if (member, key) in seen:
            raise sqlite3.IntegrityError(
                f"owner mapping required: duplicate legacy identity {(member, key)!r}")
        seen.add((member, key))
    last_end = {}
    for rid, _m, asset, start, end, _k in sorted(rows, key=lambda r: (r[2], r[3], r[4])):
        if asset in last_end and start < last_end[asset]:
            raise ValueError(f"owner mapping required: overlapping legacy intervals at {rid}")
        last_end[asset] = max(end, last_end.get(asset, end))


def init_db(path: str | Path) -> None:
    """Create or migrate to schema v3 in one transaction; refuse without any change."""
    with closing(_connect(path)) as conn:
        conn.execute("BEGIN IMMEDIATE")
        try:
            version = conn.execute("PRAGMA user_version").fetchone()[0]
            tables = _tables(conn)
            if version == SCHEMA_VERSION:
                if _TABLE not in tables:
                    raise ValueError("schema version 3 marker without reservation table")
            elif version == 2 and _TABLE in tables:
                # G2 -> G3: same IDs and public fields; every row becomes active, version 1.
                conn.execute(f"ALTER TABLE {_TABLE} ADD COLUMN state TEXT NOT NULL DEFAULT 'active'"
                             " CHECK (state IN ('active', 'cancelled'))")
                conn.execute(f"ALTER TABLE {_TABLE} ADD COLUMN version INTEGER NOT NULL DEFAULT 1")
                conn.execute(f"PRAGMA user_version = {SCHEMA_VERSION}")
            elif version != 0:
                raise ValueError(f"unsupported schema version {version}")
            else:
                legacy = [t for t in tables if t != _TABLE]
                rows = _legacy_rows(conn, legacy) if tables else []
                if _TABLE in tables:
                    raise ValueError("unversioned database already contains the v2 table")
                _check_legacy(rows)
                conn.execute(_SCHEMA)
                conn.execute(_INDEX)
                conn.executemany(
                    f"INSERT INTO {_TABLE} (id, trusted_member_id, asset_id, starts_at,"
                    " ends_at, idempotency_key, fingerprint) VALUES (?,?,?,?,?,?,?)",
                    [(r[0], r[1], r[2], r[3], r[4], r[5], _fingerprint(r[2], r[3], r[4]))
                     for r in rows])
                conn.execute(f"PRAGMA user_version = {SCHEMA_VERSION}")
            conn.execute("COMMIT")
        except BaseException:
            conn.execute("ROLLBACK")
            raise


def reserve(db_path: str | Path, *, trusted_member_id: str,
            asset_id: str, starts_at: str, ends_at: str,
            idempotency_key: str) -> Outcome:
    code = _validate(trusted_member_id, asset_id, starts_at, ends_at, idempotency_key)
    if code:
        return Outcome(422, code)
    fp = _fingerprint(asset_id, starts_at, ends_at)
    with closing(_connect(db_path)) as conn:
        conn.execute("BEGIN IMMEDIATE")  # check and insert are one write transaction
        try:
            row = conn.execute(
                f"SELECT id, fingerprint FROM {_TABLE} WHERE trusted_member_id = ?"
                " AND idempotency_key = ?", (trusted_member_id, idempotency_key)).fetchone()  # any state: replay never revives
            if row is not None:
                outcome = (Outcome(200, "confirmed", row[0], True) if row[1] == fp
                           else Outcome(409, "idempotency-key-reused"))
            elif conn.execute(
                    f"SELECT 1 FROM {_TABLE} WHERE state = 'active' AND asset_id = ? AND starts_at < ?"
                    " AND ends_at > ? LIMIT 1", (asset_id, ends_at, starts_at)).fetchone():
                outcome = Outcome(409, "interval-conflict")
            else:
                cur = conn.execute(
                    f"INSERT INTO {_TABLE} (trusted_member_id, asset_id, starts_at, ends_at,"
                    " idempotency_key, fingerprint) VALUES (?,?,?,?,?,?)",
                    (trusted_member_id, asset_id, starts_at, ends_at, idempotency_key, fp))
                outcome = Outcome(201, "confirmed", cur.lastrowid)
            conn.execute("COMMIT")
            return outcome
        except BaseException:
            conn.execute("ROLLBACK")
            raise


def get_reservation(path: str | Path, reservation_id: int):
    # Missing file -> sqlite3.OperationalError; mode=ro never creates or mutates.
    uri = Path(path).resolve().as_uri() + "?mode=ro"
    with closing(sqlite3.connect(uri, uri=True)) as conn:
        row = conn.execute(
            f"SELECT id, trusted_member_id, asset_id, starts_at, ends_at,"
            f" idempotency_key FROM {_TABLE} WHERE id = ?", (reservation_id,)).fetchone()
    if row is None:
        return None
    keys = ("reservation_id", "trusted_member_id", "asset_id", "starts_at",
            "ends_at", "idempotency_key")
    return dict(zip(keys, row))


def reservation_status(path, reservation_id):
    """Return {"state", "version"} for the reservation, or None when it does not exist."""
    uri = Path(path).resolve().as_uri() + "?mode=ro"
    with closing(sqlite3.connect(uri, uri=True)) as conn:
        row = conn.execute(f"SELECT state, version FROM {_TABLE} WHERE id = ?",
                           (reservation_id,)).fetchone()
    return None if row is None else {"state": row[0], "version": row[1]}


def cancel(path, reservation_id, *, trusted_member_id, expected_version):
    """Owner-only, version-checked cancellation; check and transition are one transaction.

    Returns a dict with status/code/reservation_id/version. Non-200 outcomes change
    nothing and do not disclose the current version.
    """
    def out(status, code, version=None):
        return {"status": status, "code": code, "reservation_id": reservation_id,
                "version": version}

    with closing(_connect(path)) as conn:
        conn.execute("BEGIN IMMEDIATE")
        try:
            row = conn.execute(
                f"SELECT trusted_member_id, state, version FROM {_TABLE} WHERE id = ?",
                (reservation_id,)).fetchone()
            if row is None:
                result = out(404, "not-found")
            elif row[0] != trusted_member_id:
                result = out(403, "not-owner")
            elif row[2] != expected_version:
                result = out(409, "stale-version")
            elif row[1] == "cancelled":
                result = out(200, "already-cancelled", row[2])
            else:
                conn.execute(f"UPDATE {_TABLE} SET state = 'cancelled', version = version + 1"
                             " WHERE id = ?", (reservation_id,))
                result = out(200, "cancelled", row[2] + 1)
            conn.execute("COMMIT")
            return result
        except BaseException:
            conn.execute("ROLLBACK")
            raise
"""Teaching reference: the first durable reservation slice,
not a deployable API.

The caller provides trusted member identity.
Authentication, HTTP, production monitoring, rate
limiting, backups, and deployment are deliberately out of
scope.
"""
from __future__ import annotations
from dataclasses import dataclass
from datetime import datetime, timedelta
import hashlib
import json
import sqlite3
from pathlib import Path
from contextlib import closing


@dataclass(frozen=True)
class Outcome:
    status: int
    code: str
    reservation_id: int | None = None
    replayed: bool = False


def init_db(path: str | Path) -> None:
    """Atomic teaching migration from three approved G1
    schema; retain old tables.
    """
    con = sqlite3.connect(str(path), timeout=10, isolation_level=None)
    try:
        con.execute("BEGIN IMMEDIATE")
        version = con.execute("PRAGMA user_version").fetchone()[0]
        if version not in (0, 2):
            raise ValueError("unsupported reservation schema")
        tables = {x[0] for x in con.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        prior = []
        if version == 0 and {"reservations", "bookings_v2"} <= tables:
            raise ValueError("two legacy representations require an owner mapping")
        if version == 0 and "reservations" in tables:
            columns = {x[1] for x in con.execute("PRAGMA table_info(reservations)")}
            if columns == {"id", "member_id", "asset_id", "starts_at", "ends_at", "request_key"}:
                prior = list(con.execute("SELECT id,member_id,asset_id,starts_at,ends_at,request_key FROM reservations"))
            elif columns == {"reservation_id", "trusted_member_id", "asset_id", "starts_at", "ends_at", "idempotency_key"}:
                # G2-OD-02 names this exact retained public-column mapping.
                prior = list(con.execute("SELECT reservation_id,trusted_member_id,asset_id,starts_at,ends_at,idempotency_key FROM reservations"))
            else:
                raise ValueError("unknown legacy schema; owner mapping required")
            con.execute("""
            ALTER TABLE reservations RENAME TO
            archived_g1_reservations
            """)
        elif version == 0 and "bookings_v2" in tables:
            for identifier, payload in con.execute("SELECT booking_no,payload FROM bookings_v2"):
                p = json.loads(payload)
                prior.append((identifier, p["trusted_member_id"], p["asset_id"], p["starts_at"], p["ends_at"], p["idempotency_key"]))
        elif version == 0 and tables:
            raise ValueError("unknown legacy schema; owner mapping required")
        con.execute("""
            CREATE TABLE IF NOT EXISTS reservations ( id INTEGER
            PRIMARY KEY AUTOINCREMENT , asset_id TEXT NOT NULL ,
            member_id TEXT NOT NULL , starts_at TEXT NOT NULL ,
            ends_at TEXT NOT NULL , request_key TEXT NOT NULL ,
            request_hash TEXT NOT NULL , UNIQUE ( member_id ,
            request_key ) )
        """)
        for identifier, member, asset, start, end, key in prior:
            if type(identifier) is not int or identifier < 1 or not all(isinstance(x, str) and x.strip() and len(x) <= 128 for x in (member, asset, key)):
                raise ValueError("invalid legacy identity; owner mapping required")
            if not timedelta(0) < _parse_utc_seconds(end) - _parse_utc_seconds(start) <= timedelta(hours=24):
                raise ValueError("invalid legacy interval; owner mapping required")
            request_hash = hashlib.sha256(json.dumps([asset,start,end], separators=(",", ":"), ensure_ascii=True).encode()).hexdigest()
            con.execute("INSERT INTO reservations VALUES(?,?,?,?,?,?,?)",
                        (identifier, asset, member, start, end, key, request_hash))
        if prior and con.execute("""
            SELECT 1 FROM reservations a JOIN reservations b ON a .
            id < b . id AND a . asset_id = b . asset_id AND a .
            starts_at < b . ends_at AND b . starts_at < a . ends_at
            LIMIT 1
        """).fetchone():
            raise ValueError("overlapping legacy rows require an owner mapping")
        con.execute("""
            CREATE INDEX IF NOT EXISTS ix_res_asset_time ON
            reservations ( asset_id , starts_at , ends_at )
        """)
        con.execute("PRAGMA user_version=2")
        con.execute("COMMIT")
    except BaseException:
        if con.in_transaction: con.execute("ROLLBACK")
        raise
    finally:
        con.close()


def _parse_utc_seconds(timestamp: str) -> datetime:
    # Strict canonical form also preserves chronological ordering as TEXT.
    if not isinstance(timestamp, str) or len(timestamp) != 20 or not timestamp.endswith('Z'):
        raise ValueError('timestamp must be YYYY-MM-DDTHH:MM:SSZ')
    dt = datetime.strptime(timestamp, '%Y-%m-%dT%H:%M:%SZ')
    if dt.strftime('%Y-%m-%dT%H:%M:%SZ') != timestamp:
        raise ValueError('noncanonical timestamp')
    return dt


def reserve(db_path: str | Path, *, trusted_member_id: str,
            asset_id: str, starts_at: str, ends_at: str,
            idempotency_key: str) -> Outcome:
    """Reserve [start,end) for an authenticated caller;
    never trusts payload identity.
    """
    if not all(
        isinstance(x, str) and x.strip() and len(x) <= 128
        for x in (trusted_member_id, asset_id, idempotency_key)
    ):
        return Outcome(422, 'invalid-identifier')
    try:
        start = _parse_utc_seconds(starts_at)
        end = _parse_utc_seconds(ends_at)
    except (ValueError, TypeError):
        return Outcome(422, 'invalid-timestamp')
    if not timedelta(0) < end - start <= timedelta(hours=24):
        return Outcome(422, 'invalid-interval')

    fingerprint = hashlib.sha256(json.dumps(
        [asset_id, starts_at, ends_at],
        separators=(',', ':'), ensure_ascii=True
    ).encode('utf-8')).hexdigest()
    con = sqlite3.connect(
        str(db_path), timeout=10, isolation_level=None
    )
    try:
        con.execute('PRAGMA busy_timeout=10000')
        # One transaction protects both check and insert.
        con.execute('BEGIN IMMEDIATE')
        prior = con.execute("""
            SELECT id, request_hash FROM reservations
            WHERE member_id = ? AND request_key = ?
        """, (trusted_member_id, idempotency_key)).fetchone()
        if prior is not None:
            con.execute('COMMIT')
            if prior[1] == fingerprint:
                return Outcome(
                    200, 'confirmed', prior[0], replayed=True
                )
            return Outcome(409, 'idempotency-key-reused')
        clash = con.execute("""
            SELECT 1 FROM reservations
            WHERE asset_id = ? AND starts_at < ? AND ends_at > ?
            LIMIT 1
        """, (asset_id, ends_at, starts_at)).fetchone()
        if clash is not None:
            con.execute('COMMIT')
            return Outcome(409, 'interval-conflict')
        cursor = con.execute("""
            INSERT INTO reservations (
                asset_id, member_id, starts_at, ends_at,
                request_key, request_hash
            ) VALUES (?,?,?,?,?,?)
        """, (asset_id, trusted_member_id, starts_at, ends_at,
              idempotency_key, fingerprint))
        reservation_id = cursor.lastrowid
        con.execute('COMMIT')
        return Outcome(201, 'confirmed', reservation_id)
    except Exception:
        if con.in_transaction:
            con.execute('ROLLBACK')
        raise
    finally:
        con.close()


def get_reservation(path: str | Path, reservation_id: int) -> dict | None:
    with closing(sqlite3.connect(Path(path).resolve().as_uri() + "?mode=ro", uri=True)) as con:
        row = con.execute("""
            SELECT id , member_id , asset_id , starts_at , ends_at ,
            request_key FROM reservations WHERE id = ?
        """, (reservation_id,)).fetchone()
    if row is None:
        return None
    return dict(zip(("reservation_id", "trusted_member_id", "asset_id",
                     "starts_at", "ends_at", "idempotency_key"), row))
# G3 decision record

## Expect

Contract RES-002/v1 (docs/contract.md): schema version 3; G2 rows migrate to `active`/version 1 with
IDs and the six public fields unchanged; `get_reservation` keeps its six-field shape even for a cancelled
row; new `reservation_status(path,id)` -> `{state,version}` or `None`; new
`cancel(path,id,*,trusted_member_id,expected_version)` with 404/not-found, 403/not-owner, 409/stale-version
(no change), 200/cancelled (version +1 once), 200/already-cancelled (current cancelled version, no
increment); cancelled intervals stop blocking; replaying the original reserve request returns the original
identity and never revives the row.

Acceptance example: member-1 reserves A 09:00-10:00 (id 1, version 1). `cancel(id=1, member-1, expected_version=1)`
-> 200/cancelled, version 2. Repeat with 2 -> 200/already-cancelled, version 2. Repeat with 1 -> 409/stale-version.
member-2 can now reserve the same slot (201). Replaying member-1's original key returns id 1, replayed=True,
status still cancelled.

Open owner question (blocking for the supplied test): `tests/test_g3.py` builds its starting database with
`legacy_booking.init_db`, which writes `PRAGMA user_version=2` and a table `reservations` with seven
columns (id, asset_id, member_id, starts_at, ends_at, request_key, request_hash). That is neither a G2
`reservations_v2` database nor one of the exact column signatures authorized by G2-OD-01/G2-OD-02, and
`booking.init_db` deliberately rejects unknown signatures ("owner mapping required"). Should that shape be
an approved migration source (map by column name, drop request_hash, recompute the fingerprint)? I did not
add it, because that would be a new data-mapping policy.

## Delegate

Edited only `booking.py` and `DOSSIER.md`. Changes in `booking.py`:
- `SCHEMA_VERSION = 3`; table `reservations_v2` gains `state` (active/cancelled, CHECK) and `version`
  (default 1). Table name kept so the public data location is unchanged.
- `init_db`: new v2 -> v3 branch (ALTER TABLE x2 + user_version, inside the existing BEGIN IMMEDIATE
  transaction, rolled back on error); v0 legacy migration and v3 re-run unchanged in behavior.
- `reserve`: interval-conflict check now counts only `state='active'` rows; idempotency lookup still
  matches any state, so a replay returns the original identity and does not revive.
- `reservation_status`: read-only (`mode=ro`) lookup.
- `cancel`: one `BEGIN IMMEDIATE` transaction does the check and the update. Check order: missing, owner,
  version, already-cancelled, transition. Owner is checked before version so a non-owner learns nothing
  about the version; non-200 results carry `version: None`. (Order is my choice where the contract lists
  outcomes without ranking them; please confirm.)
- Not touched: `get_reservation`, `Outcome`, docs, tests, `legacy_booking.py`, `prior/`, `READER_ENTRY.json`.

## Observe

1. `python3 -m unittest tests.test_g3` before edits: 7 errors, all in `setUp` at `booking.init_db`
   ("schema version 2 marker without reservation table").
2. Same command after edits: 7 errors, now `ValueError: unsupported schema version 2`, still in `setUp`.
   **The supplied development check does not pass (0/7 run past setUp).** The cause is the fixture shape
   in the open question above, not the new cancel/status code, which these tests never reached.
3. Own scratch check (outside the workspace, not part of the deliverable) using a real G2 database made
   by `prior/booking.py`, then migrated by the new `booking.init_db` (run twice): record unchanged
   (six fields); status `{active, 1}`, unknown id -> None; 404, 403, 409 as specified; active slot
   conflicts (409/interval-conflict); cancel -> 200/cancelled v2; repeat with 2 -> 200/already-cancelled
   v2; old version 1 -> 409; history record identical; new member reserves the slot (201); original
   replay -> id 1, replayed=True, state cancelled v2. All matched the contract.

## Decide

- Increment implemented and observed for G2-produced databases: ACCEPT as an implementation proposal,
  pending the operator's protected acceptance.
- Migration of the `legacy_booking` v2 seven-column shape: ASK (owner decision needed; not implemented).
- Owner-before-version check order: ASK to confirm (contract is silent on precedence).
- The task mentions "three proposals", but none are in docs/ or the workspace, so I could not rule on
  them individually.

Limits: no human approval observed. Not tested: concurrent cancels (atomicity relies on SQLite
`BEGIN IMMEDIATE`, reasoned but unexercised), refunds/deletion/staff override (out of contract), and
non-int `expected_version` (contract assumes valid typed arguments). About 12 tool commands used.
